"""Generates esp32/header_font.py from the same font the page uses.

    .venv/bin/python esp32/make_font.py

The ESP32 draws the top bar itself, and its built-in font is blocky 8x8 text.
"""

from pathlib import Path

from PIL import Image, ImageDraw, ImageFont

ROOT = Path(__file__).resolve().parent.parent
FONT = ROOT / "dashboard" / "fonts" / "LiberationSans-Bold.ttf"
SIZE = 15
HEIGHT = 18
CHARACTERS = " .:?0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"


def main() -> None:
    font = ImageFont.truetype(FONT, SIZE)
    lines = [
        "# Generated by make_font.py. Each entry is (width, MONO_HLSB pixels).",
        f"HEIGHT = {HEIGHT}",
        "GLYPHS = {",
    ]
    for character in CHARACTERS:
        width = max(round(font.getlength(character)), 1)
        image = Image.new("1", (width, HEIGHT), 0)
        draw = ImageDraw.Draw(image)
        draw.fontmode = "1"
        draw.text((0, 0), character, font=font, fill=1)
        lines.append(f"    {character!r}: ({width}, {image.tobytes()!r}),")
    lines.append("}")
    (ROOT / "esp32" / "header_font.py").write_text("\n".join(lines) + "\n")


if __name__ == "__main__":
    main()
